// "Visit today": parks, battlefields, historic sites and museums you can visit now, roadside markers
// (with their inscriptions), national park boundaries and the Overmountain Victory National Historic
// Trail. Independent of the timeline date. Data: data/visit-sites.js (curated) and data/visit-data.js
// (generated by tools/build-visit.ps1).
SC.visit = (() => {
  const { esc, distKm } = SC.util;
  const KIND = { park: 'Park', battlefield: 'Battlefield', historic: 'Historic site', museum: 'Museum / visitor center', grave: 'Grave or memorial', trail: 'Historic trail' };
  const STATUS = {
    on: ['On the battlefield', 'Preserved ground with interpretation: you can stand where the fighting happened.'],
    part: ['Part of the field', 'Some of the ground is preserved, reconstructed or open to visit.'],
    marker: ['Marker or memorial', 'A marker or memorial stands at or near the site; the ground itself is not interpreted.'],
    lost: ['Site lost', 'The ground is built over or under water. Markers or a memorial stand nearby.'],
  };
  const PROGRAM = { SC: 'South Carolina historical marker', NC: 'North Carolina highway historical marker', GA: 'Georgia historical marker', VA: 'Virginia historical highway marker' };
  const CREDIT = { SC: 'SC Dept. of Archives & History', NC: 'NC Dept. of Natural and Cultural Resources', GA: 'Georgia Historical Society', VA: 'Virginia Dept. of Historic Resources' };
  const MARKER_LAYERS = ['visit-park-fill', 'visit-park-line', 'visit-trail', 'visit-offset', 'visit-markers'];
  // A curated battlefield pin this close to its own battle's icon adds nothing on the map (the battle icon
  // stands for it, and the battle panel lists it), so it is not drawn
  const SAME_SITE_KM = 2.5;
  let map, on = false, popup;
  const els = {};
  const sites = () => SC.visitSites || [];
  const data = () => SC.visitData || { markers: [], parks: { type: 'FeatureCollection', features: [] }, trail: { type: 'FeatureCollection', features: [] } };

  // What a place is, in words, so it is never mistaken for one of the map's battle icons
  function typeLabel(s) {
    if (s.kind === 'battlefield' || ['marker', 'lost'].includes(s.status)) {
      return { on: 'Battlefield site', part: 'Battlefield site (part preserved)', marker: 'Marker / memorial', lost: 'Site lost: marker / memorial' }[s.status] || 'Battlefield site';
    }
    return { park: 'Park', historic: 'Historic site', museum: 'Museum', grave: 'Grave / memorial', trail: 'Historic trail' }[s.kind] || 'Place';
  }
  // Visit pins never use the crossed-swords battle icon
  const icon = (s) => SC.icons.get(s.kind === 'battlefield' ? (['on', 'part'].includes(s.status) ? 'park' : 'marker') : s.kind, 'historic');
  const ownBattle = (s) => (s.battles || []).map((id) => SC.battles.find((b) => b.id === id)).find(Boolean);
  const hidden = (s) => { const b = s.kind === 'battlefield' && ownBattle(s); return !!b && distKm([b.lon, b.lat], s.ll) < SAME_SITE_KM; };

  const directions = ([lon, lat]) => `https://www.google.com/maps/dir/?api=1&destination=${lat.toFixed(5)},${lon.toFixed(5)}`;
  const kmText = (km) => (km < 1 ? `${Math.round(km * 1000 / 10) * 10} m` : `${km.toFixed(km < 10 ? 1 : 0)} km`) + ` (${(km * 0.621).toFixed(km < 16 ? 1 : 0)} mi)`;
  const paras = (t) => t.split(/\n\n+/).map((p) => `<p>${esc(p)}</p>`).join('');

  function addLayers(m) {
    map = m;
    const d = data();
    map.addSource('visit-parks', { type: 'geojson', data: d.parks });
    map.addSource('visit-trail', { type: 'geojson', data: d.trail });
    map.addSource('visit-markers', { type: 'geojson', data: { type: 'FeatureCollection', features: d.markers.map((mk, i) => ({ type: 'Feature', id: i, properties: { i }, geometry: { type: 'Point', coordinates: mk.ll } })) } });
    // Dashed lines from a battle's site to where its marker or memorial actually stands, when they differ
    const offs = [];
    for (const s of sites()) {
      if (!['marker', 'lost'].includes(s.status) || hidden(s)) continue;
      for (const id of s.battles || []) {
        const b = SC.battles.find((x) => x.id === id);
        if (b && distKm([b.lon, b.lat], s.ll) > 0.4) offs.push({ type: 'Feature', properties: {}, geometry: { type: 'LineString', coordinates: [[b.lon, b.lat], s.ll] } });
      }
    }
    map.addSource('visit-offset', { type: 'geojson', data: { type: 'FeatureCollection', features: offs } });
    const vis = { visibility: 'none' };
    map.addLayer({ id: 'visit-park-fill', type: 'fill', source: 'visit-parks', layout: vis, paint: { 'fill-color': '#5f9e4a', 'fill-opacity': 0.18 } });
    map.addLayer({ id: 'visit-park-line', type: 'line', source: 'visit-parks', layout: vis, paint: { 'line-color': '#8fd16f', 'line-width': 1.6, 'line-opacity': 0.9 } });
    map.addLayer({ id: 'visit-trail', type: 'line', source: 'visit-trail', layout: { ...vis, 'line-cap': 'round', 'line-join': 'round' },
      paint: { 'line-color': '#e7a948', 'line-width': ['interpolate', ['linear'], ['zoom'], 6, 1.5, 12, 3.5], 'line-dasharray': [2, 1.5], 'line-opacity': 0.9 } });
    map.addLayer({ id: 'visit-offset', type: 'line', source: 'visit-offset', layout: vis, paint: { 'line-color': '#f3e3b0', 'line-width': 1.4, 'line-dasharray': [1, 2] } });
    map.addLayer({ id: 'visit-markers', type: 'circle', source: 'visit-markers', layout: vis, minzoom: 6,
      paint: { 'circle-radius': ['interpolate', ['linear'], ['zoom'], 6, 2.5, 12, 5.5], 'circle-color': '#3a2f22',
        'circle-stroke-color': '#e5c46b', 'circle-stroke-width': ['interpolate', ['linear'], ['zoom'], 6, 1, 12, 2],
        'circle-opacity': ['case', ['boolean', ['feature-state', 'hover'], false], 1, 0.9] } });

    // Roadside markers: title, where it stands, the start of the inscription with "Read more"
    popup = new maplibregl.Popup({ closeButton: true, maxWidth: '280px', className: 'visit-pop', focusAfterOpen: false });
    map.on('click', 'visit-markers', (e) => openMarker(e.features[0].properties.i, false));
    map.on('mouseenter', 'visit-markers', () => { map.getCanvas().style.cursor = 'pointer'; });
    map.on('mouseleave', 'visit-markers', () => { map.getCanvas().style.cursor = ''; });

    for (const s of sites()) {
      if (hidden(s)) continue;
      const type = typeLabel(s);
      const el = document.createElement('div');
      el.className = `visit-site kind-${s.kind}${s.status ? ` st-${s.status}` : ''}`;
      el.innerHTML = `<span class="vs-icon">${icon(s)}</span><span class="vs-label">${esc(s.name)}<small>${esc(type)}</small></span>`;
      el.title = `${s.name} (${type})`;
      el.style.display = 'none';
      el.addEventListener('click', (e) => { e.stopPropagation(); open(s.id); });
      els[s.id] = new maplibregl.Marker({ element: el, anchor: 'left', offset: [-11, 0] }).setLngLat(s.ll).addTo(map);
    }
    const zoomCls = () => map.getContainer().classList.toggle('visit-labels', map.getZoom() >= 9);
    map.on('zoom', zoomCls); zoomCls();
  }

  const EXCERPT = 210;
  // Markers that stand together (both sides of a road, a town square, a churchyard) draw as one dot
  const SAME_SPOT_KM = 0.06;
  const alsoHere = (i) => { const ll = data().markers[i].ll; return data().markers.map((m, j) => j).filter((j) => j !== i && distKm(ll, data().markers[j].ll) < SAME_SPOT_KM); };
  function markerHTML(mk, full, others) {
    const t = mk.text || '';
    const long = t.length > EXCERPT + 40;
    const shown = !long || full ? paras(t) : `<p>${esc(t.slice(0, t.lastIndexOf(' ', EXCERPT)))}…</p>`;
    const link = mk.url ? `<a href="${esc(mk.url)}" target="_blank" rel="noopener">${mk.st === 'SC' ? 'On the SCDAH map' : 'Marker page'}</a>` : '';
    return `<div class="vp-kind">${SC.icons.get('marker')} ${esc(PROGRAM[mk.st])} ${esc(mk.no)}</div>
      <strong>${esc(mk.name)}</strong>${mk.where ? `<div class="vp-where">${esc(mk.where)}</div>` : ''}${mk.note ? `<div class="vp-note">${esc(mk.note)}</div>` : ''}
      ${t ? `<div class="vp-text${full ? ' full' : ''}">${shown}</div>${long ? `<button type="button" class="vp-more">${full ? 'Show less' : 'Read more'}</button>` : ''}
        <div class="vp-credit">Inscription: ${esc(CREDIT[mk.st])}</div>` : ''}
      <div class="vp-links">${link}<a href="${directions(mk.ll)}" target="_blank" rel="noopener">Directions</a></div>
      ${others.length ? `<div class="vp-also"><span>Also at this spot:</span>${others.map((j) => `<button type="button" data-mk="${j}">${esc(data().markers[j].name)}</button>`).join('')}</div>` : ''}`;
  }
  function renderMarker(i, full) {
    const mk = data().markers[i];
    popup.setMaxWidth(full ? '400px' : '280px').setHTML(markerHTML(mk, full, alsoHere(i)));
    const el = popup.getElement();
    el?.querySelector('.vp-more')?.addEventListener('click', () => renderMarker(i, !full));
    el?.querySelectorAll('[data-mk]').forEach((b) => b.addEventListener('click', () => renderMarker(+b.dataset.mk, false)));
  }
  function openMarker(i, fly) {
    const mk = data().markers[i];
    if (fly) map.flyTo({ center: mk.ll, zoom: Math.max(map.getZoom(), 13), duration: 1200, essential: true });
    popup.setLngLat(mk.ll);
    if (!popup.isOpen()) popup.addTo(map);
    renderMarker(i, false);
  }

  function setOn(v) {
    on = v;
    for (const id of MARKER_LAYERS) if (map.getLayer(id)) map.setLayoutProperty(id, 'visibility', on ? 'visible' : 'none');
    for (const mk of Object.values(els)) mk.getElement().style.display = on ? '' : 'none';
    if (!on) popup?.remove();
    document.body.classList.toggle('visit-on', on);
  }

  // Roadside markers for a battle: those within 5 km, plus markers farther off (up to 40 km) whose title
  // names the action
  const NEAR_KM = 5, NAMED_KM = 40;
  const GENERIC = new Set(['battle', 'siege', 'raid', 'first', 'second', 'capture', 'standoff', 'little', 'great', 'the', 'and', 'swamp', 'creek', 'ford', 'ferry', 'bridge', 'mill', 'hill', 'island', 'fort', 'springs', 'store', 'plantation', 'courthouse', 'court', 'house', 'corner', 'lower', 'upper', 'mount', 'rock', 'black', 'river', 'road', 'county', 'street', 'defeat', 'massacre']);
  const ALIASES = { wiboo_lower_bridge: ['wyboo', 'lower bridge'], fishdam_ford: ['fish dam'], monks_corner: ['moncks corner', 'biggin'], great_savannah: ['nelson'], hucks_defeat: ['williamson', 'bratton'], the_hook: ['tarleton', 'gloucester point'], race_to_dan: ['dan river', 'boyd', 'irwin'] };
  const words = (s) => s.toLowerCase().replace(/[’']s\b/g, '').replace(/[^a-z ]/g, ' ').split(/\s+/).filter((w) => w.length >= 4 && !GENERIC.has(w));
  function markersFor(b) {
    const keys = [...words(b.name.replace(/\(.*?\)/g, '')), ...(ALIASES[b.id] || [])];
    return data().markers.map((mk, i) => ({ mk, i, km: distKm([b.lon, b.lat], mk.ll) }))
      .filter(({ mk, km }) => km < NEAR_KM || (km < NAMED_KM && keys.some((k) => (k.includes(' ') ? mk.name.toLowerCase().includes(k) : words(mk.name).some((w) => w.startsWith(k) || k.startsWith(w))))))
      .sort((x, y) => x.km - y.km);
  }

  // Places listed for a battle: its own sites first (best status first), then related places
  const ORDER = { on: 0, part: 1, marker: 2, lost: 3 };
  function forBattle(b) {
    return sites().filter((s) => (s.battles || []).includes(b.id))
      .map((s) => ({ s, km: distKm([b.lon, b.lat], s.ll) }))
      .sort((x, y) => (ORDER[x.s.status] ?? 5) - (ORDER[y.s.status] ?? 5) || x.km - y.km);
  }

  // A "Visit today" block for the battle panel
  const MAX_LISTED = 12;
  function battleSection(b) {
    popup?.remove();
    const list = forBattle(b), mks = markersFor(b);
    if (!list.length && !mks.length) return '';
    const items = list.map(({ s, km }) => `<li><a href="#" data-visit="${esc(s.id)}">${icon(s)}<span>${esc(s.name)}</span></a>
      ${s.status ? `<em class="visit-status ${s.status}" title="${esc(STATUS[s.status][1])}">${esc(STATUS[s.status][0])}</em>` : `<em class="visit-type">${esc(typeLabel(s))}</em>`}
      ${(s.status ? ['marker', 'lost'].includes(s.status) && km > 0.4 : km > 2) ? `<small>${kmText(km)} from the battle site</small>` : ''}</li>`).join('');
    const mkItems = mks.slice(0, MAX_LISTED).map(({ mk, i, km }) => `<li><a href="#" data-marker="${i}">${SC.icons.get('marker')}<span>${esc(mk.name)}</span></a>
      <small>${esc(mk.st)} marker ${esc(mk.no)} · ${kmText(km)} away${mk.note ? ` · ${esc(mk.note.toLowerCase())}` : ''}</small></li>`).join('');
    return `<div class="visit-sec"><h4>Visit today</h4>${items ? `<ul>${items}</ul>` : ''}
      ${mkItems ? `<h5>Historical markers</h5><ul class="visit-mk">${mkItems}</ul>
        ${mks.length > MAX_LISTED ? `<div class="src">${mks.length - MAX_LISTED} more nearby.</div>` : ''}
        <div class="src"><a href="#" data-visit-on="1">Show the markers on the map</a></div>` : ''}</div>`;
  }
  function wire(panel, b) {
    panel.querySelectorAll('[data-visit]').forEach((a) => a.addEventListener('click', (e) => { e.preventDefault(); toggle(true); open(a.dataset.visit); }));
    panel.querySelectorAll('[data-marker]').forEach((a) => a.addEventListener('click', (e) => { e.preventDefault(); toggle(true); openMarker(+a.dataset.marker, true); }));
    panel.querySelector('[data-visit-on]')?.addEventListener('click', (e) => {
      e.preventDefault(); toggle(true);
      map.flyTo({ center: [b.lon, b.lat], zoom: 11.5, pitch: 45, duration: 1500, essential: true });
    });
  }
  function toggle(v) {
    const cb = document.getElementById('visit-toggle');
    if (cb.checked !== v) { cb.checked = v; }
    setOn(v);
  }

  function open(id) {
    const s = sites().find((x) => x.id === id); if (!s) return;
    const bats = (s.battles || []).map((bid) => SC.battles.find((x) => x.id === bid)).filter(Boolean);
    const own = s.status && bats[0];
    const km = own ? distKm([bats[0].lon, bats[0].lat], s.ll) : 0;
    const body = SC.panel.show('visit', `
      <div class="kicker">${esc(typeLabel(s))} · Visit today</div>
      <h2>${esc(s.name)}</h2>
      ${s.status ? `<span class="visit-status ${s.status}" title="${esc(STATUS[s.status][1])}">${esc(STATUS[s.status][0])}</span>
        <p class="src">${esc(STATUS[s.status][1])}${['marker', 'lost'].includes(s.status) && km > 0.4 ? ` About ${kmText(km)} from where the map places the battle.` : ''}</p>` : ''}
      ${s.note ? `<p>${esc(s.note)}</p>` : ''}
      ${bats.length ? `<div class="loc-line"><span class="k">${bats.length > 1 ? 'Battles' : 'Battle'}</span> ${bats.map((b) => `<a href="#" data-battle="${b.id}">${esc(b.name)}</a>`).join(', ')}</div>` : ''}
      <div class="info-actions">
        ${s.url ? `<a class="btn primary" href="${esc(s.url)}" target="_blank" rel="noopener">${s.src === 'lt' ? 'Liberty Trail page' : 'Official page'}</a>` : ''}
        <a class="btn" href="${directions(s.ll)}" target="_blank" rel="noopener">Directions</a>
      </div>
      <div class="src">Check opening hours, fees and access with the site before you go.${s.src === 'lt' ? ' Position and page: The Liberty Trail.' : ''}</div>`);
    body.querySelectorAll('[data-battle]').forEach((a) => a.addEventListener('click', (e) => { e.preventDefault(); SC.battles_ui.select(a.dataset.battle, true); }));
    map.flyTo({ center: s.ll, zoom: Math.max(map.getZoom(), 12), duration: 1200, essential: true });
  }

  return { addLayers, setOn, battleSection, wire, open, openMarker, isOn: () => on };
})();
